{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "To be included in this review, studies had to explore facilitators and/or barriers to PA in older patients during hospitalization. Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; 3) they used a quantitative, qualitative, or mixed-methods study design; and 4) the study population consisted of patients aged ≥ 65 years (baseline mean age of 65 years or older), caregivers, or HCPs.",
      "reason": "Eligibility is specified for study question/context (older patients during hospitalization), study designs (quantitative/qualitative/mixed-methods), and study population. However, follow-up requirements are not described, and the evidence does not fully specify all framework components for eligibility (e.g., follow-up)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies were included if: 1) they were published between January 1, 2000, and May 29, 2021; 2) they were written in English, German, or Dutch; and 3) they used a quantitative, qualitative, or mixed-methods study design; and 4) the study population consisted of patients aged ≥ 65 years (baseline mean age of 65 years or older), caregivers, or HCPs.",
      "reason": "The review specifies publication date range and eligible languages. No explicit statement is provided about publication/report status (e.g., published vs. unpublished), but the required elements related to year and language are present."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not describe a distinction between exclusions because outcomes were not measured versus exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Furthermore, 12 studies [49, 51, 53, 56, 72, 74, 76-80, 83] investigated the effects of a PA intervention by comparing two study population groups.",
      "reason": "The evidence indicates that, for at least some analyses, studies were grouped by comparing two study population groups. However, the evidence provided does not clearly specify the groups used in each synthesis or explicitly link those groups to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies were excluded if they were: 1) editorials, opinion papers, conference abstracts, or literature reviews; 2) targeting patients with moderate to severe dementia according to standard diagnostic criteria (e.g., DSM4-TR, DSM-5, NINCDS-ADRDA, and NINCDS-AIREN) or palliative patients; 3) studies with no original participant data regarding barriers and facilitators; and 4) studies that were performed in an inpatient rehabilitation or psychiatric unit, or in healthcare settings other than hospitals, such as outpatient clinics.",
      "reason": "Notable eligibility restrictions are listed with reasons/explanations via the explicit exclusion categories (e.g., excluding non-original research, dementia/palliative populations, non-hospital settings, and studies lacking original participant data)."
    }
  ],
  "confidence": 62
}

